/**
 * Parse CSV text into an array of rows, each row an array of strings.
 *
 * Rules:
 * - Fields are separated by commas.
 * - A field wrapped in double quotes may contain commas and line breaks,
 *   and a doubled quote ("") inside it means one double quote.
 * - Lines end with \n or \r\n.
 * - A final line break does not add an empty row, and empty text gives [].
 */
export function parseCsv(text) {
  const input = typeof text === 'string' ? text : String(text ?? '');
  if (input.length === 0) return [];

  const rows = [];
  let row = [];
  let field = '';
  let inQuotes = false;
  let fieldStarted = false;

  const endField = () => {
    row.push(field);
    field = '';
    fieldStarted = false;
  };

  const endRow = () => {
    endField();
    rows.push(row);
    row = [];
  };

  for (let i = 0; i < input.length; i += 1) {
    const ch = input[i];

    if (inQuotes) {
      if (ch === '"') {
        if (input[i + 1] === '"') {
          field += '"';
          i += 1;
        } else {
          inQuotes = false;
        }
      } else {
        field += ch;
      }
      continue;
    }

    if (ch === '"' && !fieldStarted) {
      inQuotes = true;
      fieldStarted = true;
      continue;
    }

    if (ch === ',') {
      endField();
      continue;
    }

    if (ch === '\r') {
      if (input[i + 1] === '\n') i += 1;
      endRow();
      continue;
    }

    if (ch === '\n') {
      endRow();
      continue;
    }

    field += ch;
    fieldStarted = true;
  }

  // A final line break does not add a trailing empty row.
  const endedWithRowBreak =
    input.endsWith('\n') || input.endsWith('\r') || !fieldStarted;
  if (!endedWithRowBreak || field.length > 0 || row.length > 0) {
    // Only push a pending row when there is something left over.
    if (!(row.length === 0 && field === '')) endRow();
  }

  return rows;
}

/**
 * Map parsed CSV rows to objects.
 * The first row is the header; each remaining row becomes an object keyed by
 * the header names. Missing columns on a short row become empty strings.
 */
export function toObjects(rows) {
  if (!Array.isArray(rows) || rows.length === 0) return [];
  const header = rows[0];
  const objects = [];

  for (let r = 1; r < rows.length; r += 1) {
    const row = rows[r];
    const obj = {};
    for (let c = 0; c < header.length; c += 1) {
      const value = row[c];
      obj[header[c]] = value === undefined || value === null ? '' : value;
    }
    objects.push(obj);
  }

  return objects;
}

