import test from 'node:test';
import assert from 'node:assert/strict';
import { parseCsv, toObjects } from '../src/csv.js';

test('parses simple comma separated rows into arrays of strings (c1)', () => {
  assert.deepEqual(parseCsv('a,b,c\nd,e,f'), [
    ['a', 'b', 'c'],
    ['d', 'e', 'f'],
  ]);
});

test('returns strings for every field (c1)', () => {
  const rows = parseCsv('1,2\n3,4');
  for (const row of rows) {
    for (const field of row) assert.equal(typeof field, 'string');
  }
});

test('keeps empty fields', () => {
  assert.deepEqual(parseCsv('a,,c'), [['a', '', 'c']]);
  assert.deepEqual(parseCsv(',,'), [['', '', '']]);
});

test('quoted fields may contain commas and line breaks (c2)', () => {
  assert.deepEqual(parseCsv('a,"b,c",d'), [['a', 'b,c', 'd']]);
  assert.deepEqual(parseCsv('"line1\nline2",x'), [['line1\nline2', 'x']]);
});

test('doubled quotes inside a quoted field mean one quote (c2)', () => {
  assert.deepEqual(parseCsv('"he said ""hi""",x'), [['he said "hi"', 'x']]);
  assert.deepEqual(parseCsv('""""'), [['"']]);
});

test('handles LF and CRLF line endings (c3)', () => {
  assert.deepEqual(parseCsv('a,b\r\nc,d'), [
    ['a', 'b'],
    ['c', 'd'],
  ]);
  assert.deepEqual(parseCsv('a,b\nc,d'), [
    ['a', 'b'],
    ['c', 'd'],
  ]);
});

test('a final line break does not add an empty row (c3)', () => {
  assert.deepEqual(parseCsv('a,b\n'), [['a', 'b']]);
  assert.deepEqual(parseCsv('a,b\r\n'), [['a', 'b']]);
});

test('empty text gives [] (c3)', () => {
  assert.deepEqual(parseCsv(''), []);
});

test('toObjects uses the first row as header (c4)', () => {
  assert.deepEqual(toObjects(parseCsv('name,age\nAda,36\nAlan,41')), [
    { name: 'Ada', age: '36' },
    { name: 'Alan', age: '41' },
  ]);
});

test('toObjects pads short rows with empty strings (c4)', () => {
  assert.deepEqual(toObjects(parseCsv('a,b,c\n1,2')), [{ a: '1', b: '2', c: '' }]);
});

test('toObjects returns [] for header-only or empty input (c4)', () => {
  assert.deepEqual(toObjects(parseCsv('a,b')), []);
  assert.deepEqual(toObjects([]), []);
});

test('round trip with quoted commas and CRLF', () => {
  const rows = parseCsv('id,note\r\n1,"hello, world"\r\n2,"say ""ok"""\r\n');
  assert.deepEqual(toObjects(rows), [
    { id: '1', note: 'hello, world' },
    { id: '2', note: 'say "ok"' },
  ]);
});

import { parseCsv, toObjects } from '../src/csv.js';

const show = (label, value) => console.log(label, JSON.stringify(value));

show('simple    ', parseCsv('a,b,c\nd,e,f'));
show('quoted    ', parseCsv('a,"b,c",d'));
show('multiline ', parseCsv('"line1\nline2",x'));
show('doubled   ', parseCsv('"he said ""hi""",x'));
show('crlf      ', parseCsv('a,b\r\nc,d'));
show('trailing  ', parseCsv('a,b\n'));
show('trailingCR', parseCsv('a,b\r\n'));
show('empty     ', parseCsv(''));
show('objects   ', toObjects(parseCsv('name,age\nAda,36\nAlan,41')));
show('short row ', toObjects(parseCsv('a,b,c\n1,2')));
show('headeronly', toObjects(parseCsv('a,b')));
